package id.tapledger.app;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.pdf.PdfDocument;
import android.nfc.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.io.*;
import java.text.*;
import java.util.*;

/** Working alpha: NFC technology discovery + local card registry + manual ledger + PDF receipts.
 *  No bank-specific balance/history decoder is included; no unverified financial data is shown.
 */
public class MainActivity extends Activity implements NfcAdapter.ReaderCallback {
    private final int NAVY=Color.rgb(15,35,63), BLUE=Color.rgb(0,108,206), GREY=Color.rgb(102,116,134), BG=Color.rgb(247,249,252);
    private Store store; private NfcAdapter nfc; private LinearLayout root,content; private String selected=""; private String page="home";
    private String pendingCsv="";
    private final SimpleDateFormat fmt=new SimpleDateFormat("dd MMM yyyy, HH:mm",new Locale("id","ID"));
    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);store=new Store(this);nfc=NfcAdapter.getDefaultAdapter(this);showHome();}
    @Override protected void onResume(){super.onResume();if(nfc!=null) nfc.enableReaderMode(this,this,NfcAdapter.FLAG_READER_NFC_A|NfcAdapter.FLAG_READER_NFC_B|NfcAdapter.FLAG_READER_NFC_F|NfcAdapter.FLAG_READER_NFC_V|NfcAdapter.FLAG_READER_SKIP_NDEF_CHECK,null);}
    @Override protected void onPause(){if(nfc!=null)nfc.disableReaderMode(this);super.onPause();}
    @Override public void onTagDiscovered(Tag tag){
        // NFC Tag.getId() is not a secure identity and may be randomized or cloned; local convenience only.
        byte[] raw=tag.getId();StringBuilder sb=new StringBuilder();for(byte b:raw)sb.append(String.format(Locale.US,"%02X",b&255));
        String id=sb.toString();if(id.isEmpty())return;
        String tech=android.text.TextUtils.join(", ",tag.getTechList());
        store.saveScan(id,tech);
        runOnUiThread(()->{selected=id;showCard(id);new AlertDialog.Builder(this).setTitle("Kartu NFC terdeteksi").setMessage("Identitas teknis dan waktu pemindaian telah tersimpan. Saldo, penerbit, dan transaksi belum dapat diverifikasi tanpa decoder khusus kartu.\n\nID lokal: ••••"+id.substring(Math.max(0,id.length()-4))).setPositiveButton("OK",null).show();});
    }
    private int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    private TextView text(String t,int sz,int color,boolean bold){TextView x=new TextView(this);x.setText(t);x.setTextSize(sz);x.setTextColor(color);x.setPadding(dp(2),dp(5),dp(2),dp(5));if(bold)x.setTypeface(null,1);return x;}
    private LinearLayout column(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;}
    private void space(LinearLayout l,int n){View v=new View(this);l.addView(v,new LinearLayout.LayoutParams(1,dp(n)));}
    private LinearLayout card(LinearLayout parent){LinearLayout box=column();android.graphics.drawable.GradientDrawable shape=new android.graphics.drawable.GradientDrawable();shape.setColor(Color.WHITE);shape.setCornerRadius(dp(18));box.setBackground(shape);box.setPadding(dp(17),dp(15),dp(17),dp(15));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);parent.addView(box,p);return box;}
    private void btn(LinearLayout p,String title,Runnable action){Button b=new Button(this);b.setText(title);b.setTextAllCaps(false);b.setOnClickListener(v->action.run());p.addView(b,new LinearLayout.LayoutParams(-1,dp(52)));}
    private void init(String title,String subtitle){root=column();root.setBackgroundColor(BG);setContentView(root);ScrollView sc=new ScrollView(this);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));content=column();content.setPadding(dp(19),dp(25),dp(19),dp(16));sc.addView(content);content.addView(text(title,27,NAVY,true));content.addView(text(subtitle,13,GREY,false));space(content,20);LinearLayout nav=column();nav.setPadding(dp(14),dp(6),dp(14),dp(10));root.addView(nav);LinearLayout bar=new LinearLayout(this);nav.addView(bar);navItem(bar,"Beranda",()->showHome());navItem(bar,"Kartu",()->showCards());navItem(bar,"Riwayat",()->showHistory());navItem(bar,"Info",()->showInfo());}
    private void navItem(LinearLayout b,String t,Runnable action){Button v=new Button(this);v.setText(t);v.setTextSize(11);v.setAllCaps(false);b.addView(v,new LinearLayout.LayoutParams(0,dp(48),1));v.setOnClickListener(w->action.run());}
    private void showHome(){page="home";init("TapLedger","Dompet kartu NFC • Data tersimpan di perangkat");LinearLayout c=card(content);c.addView(text("TEMPELKAN KARTU DI BELAKANG HP",16,NAVY,true));c.addView(text(nfc==null?"NFC tidak tersedia pada perangkat ini":!nfc.isEnabled()?"NFC nonaktif. Aktifkan dari Pengaturan Android.":"NFC aktif · Pemindaian siap",15,nfc!=null&&nfc.isEnabled()?BLUE:GREY,true));c.addView(text("Saldo dan riwayat finansial tidak ditampilkan sampai protokol kartu berhasil diverifikasi.",12,GREY,false));btn(c,"Lihat kartu tersimpan",()->showCards());LinearLayout s=card(content);s.addView(text("RINGKASAN LOKAL",13,GREY,true));s.addView(text(store.cards().size()+" kartu dikenali · "+store.scanCount()+" kali dipindai",21,NAVY,true));s.addView(text(store.transactions("").size()+" transaksi dicatat manual",14,GREY,false));btn(s,"Tambah catatan transaksi",()->chooseCard());btn(s,"Cari struk tol di situs operator",()->startActivity(new Intent(this,TollPortalActivity.class)));LinearLayout sec=card(content);sec.addView(text("Yang sudah tersedia",15,NAVY,true));sec.addView(text("• Deteksi NFC langsung\n• Daftar kartu dan log pemindaian\n• Riwayat transaksi manual per kartu\n• Struk PDF berlabel catatan pribadi\n• Beroperasi offline untuk catatan lokal\n• Portal resmi AstraTol untuk pencarian struk (perlu internet)",14,GREY,false));}
    private void showCards(){page="cards";init("Kartu saya","Tap kartu NFC untuk menambahkannya secara otomatis");ArrayList<String[]> cards=store.cards();if(cards.isEmpty()){card(content).addView(text("Belum ada kartu. Tempelkan kartu NFC untuk memulai.",16,GREY,false));return;}for(String[] a:cards){LinearLayout c=card(content);c.addView(text(a[1],18,NAVY,true));c.addView(text("Terakhir dipindai: "+fmt.format(new Date(Long.parseLong(a[3]))),13,GREY,false));c.addView(text("Teknologi: "+a[2],11,GREY,false));btn(c,"Detail kartu",()->showCard(a[0]));}}
    private void showCard(String id){page="card";selected=id;init("Detail kartu","ID lokal ••••"+id.substring(Math.max(0,id.length()-4)));LinearLayout c=card(content);c.addView(text("Saldo: belum tersedia",19,NAVY,true));c.addView(text("Identitas penerbit dan saldo tidak dapat disimpulkan hanya dari UID NFC.",13,GREY,false));btn(c,"Tambah transaksi manual",()->transactionDialog(id));btn(c,"Lihat riwayat kartu",()->showHistory(id));btn(c,"Cari struk tol online (AstraTol)",()->startActivity(new Intent(this,TollPortalActivity.class)));btn(c,"Ubah nama kartu",()->renameDialog(id));}
    private void showHistory(){showHistory("");}
    private void renameDialog(String id){EditText e=new EditText(this);e.setSingleLine(true);e.setHint("Nama kartu, misal e-Money mobil");new AlertDialog.Builder(this).setTitle("Ubah nama kartu").setView(e).setNegativeButton("Batal",null).setPositiveButton("Simpan",(d,w)->{String n=e.getText().toString().trim();if(!n.isEmpty()){store.renameCard(id,n);showCards();}}).show();}
    private String csvCell(String value){return "\""+value.replace("\"","\"\"").replace("\r"," ").replace("\n"," ")+"\"";}
    private void exportCsv(String filter){StringBuilder sb=new StringBuilder("id,kartu,tanggal,nominal,kategori,merchant,lokasi,catatan,sumber,operator\r\n");for(String[] r:store.transactions(filter)){for(int i=0;i<r.length;i++){if(i>0)sb.append(',');String v=r[i]==null?"":r[i];if(i==2)v=fmt.format(new Date(Long.parseLong(v)));sb.append(csvCell(v));}sb.append("\r\n");}pendingCsv=sb.toString();Intent in=new Intent(Intent.ACTION_CREATE_DOCUMENT);in.addCategory(Intent.CATEGORY_OPENABLE);in.setType("text/csv");in.putExtra(Intent.EXTRA_TITLE,"tapledger_riwayat.csv");startActivityForResult(in,41);}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==41&&result==RESULT_OK&&data!=null&&data.getData()!=null){try(java.io.OutputStream stream=getContentResolver().openOutputStream(data.getData())){if(stream!=null)stream.write(pendingCsv.getBytes(java.nio.charset.StandardCharsets.UTF_8));Toast.makeText(this,"CSV berhasil disimpan",Toast.LENGTH_LONG).show();}catch(Exception ex){Toast.makeText(this,"Gagal ekspor: "+ex.getMessage(),Toast.LENGTH_LONG).show();}finally{pendingCsv="";}}}

    private void showHistory(String filter){page="history";init("Riwayat transaksi",filter.isEmpty()?"Seluruh kartu • Data lokal":"Kartu ••••"+filter.substring(Math.max(0,filter.length()-4)));ArrayList<String[]> all=store.transactions(filter);if(all.isEmpty()){LinearLayout c=card(content);c.addView(text("Belum ada transaksi tersimpan.",16,GREY,false));btn(c,"Tambah transaksi",()->chooseCard());return;}long spent=0;for(String[] r:all){long a=Long.parseLong(r[3]);if(a<0)spent+=-a;}LinearLayout tot=card(content);tot.addView(text("Total pengeluaran yang dicatat",14,GREY,false));tot.addView(text(money(spent),24,NAVY,true));tot.addView(text("Bukan angka transaksi bank yang diverifikasi.",12,GREY,false));btn(tot,"Ekspor riwayat CSV",()->exportCsv(filter));for(String[] r:all){LinearLayout c=card(content);c.addView(text(r[4]+" · "+r[5],16,NAVY,true));c.addView(text(fmt.format(new Date(Long.parseLong(r[2])))+"   "+money(Long.parseLong(r[3])),15,Long.parseLong(r[3])<0?Color.rgb(179,58,58):BLUE,true));c.addView(text(r[6]+(r[9].isEmpty()?"":" · Operator: "+r[9]),13,GREY,false));c.addView(text("Sumber: INPUT MANUAL — bukan bukti pembayaran resmi",11,GREY,false));btn(c,"Buat struk PDF",()->exportPdf(r));}}
    private void chooseCard(){ArrayList<String[]> cs=store.cards();if(cs.isEmpty()){new AlertDialog.Builder(this).setMessage("Pindai kartu NFC terlebih dahulu.").setPositiveButton("OK",null).show();return;}String[] names=new String[cs.size()];for(int i=0;i<cs.size();i++)names[i]=cs.get(i)[1];new AlertDialog.Builder(this).setTitle("Pilih kartu").setItems(names,(d,w)->transactionDialog(cs.get(w)[0])).show();}
    private EditText field(LinearLayout l,String hint,boolean numeric){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(hint);if(numeric)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_SIGNED);l.addView(e);return e;}
    private void transactionDialog(String id){LinearLayout f=column();f.setPadding(dp(22),dp(8),dp(22),0);TextView warn=text("Catatan pribadi (bukan transaksi terverifikasi)",12,GREY,true);f.addView(warn);EditText amount=field(f,"Jumlah (+ isi ulang, - pengeluaran)",true);EditText category=field(f,"Kategori (Tol / Parkir / MRT / Belanja)",false);EditText merchant=field(f,"Merchant / gerbang tol",false);EditText location=field(f,"Lokasi (opsional)",false);EditText operator=field(f,"Operator terverifikasi (opsional)",false);EditText notes=field(f,"Catatan",false);new AlertDialog.Builder(this).setTitle("Catat transaksi").setView(f).setNegativeButton("Batal",null).setPositiveButton("Simpan",(d,w)->{try{long amt=Long.parseLong(amount.getText().toString().trim());if(amt==0)throw new Exception();String cat=category.getText().toString().trim();String mer=merchant.getText().toString().trim();if(cat.isEmpty()||mer.isEmpty())throw new Exception();store.addTransaction(id,System.currentTimeMillis(),amt,cat,mer,location.getText().toString().trim(),notes.getText().toString().trim(),operator.getText().toString().trim());showHistory(id);}catch(Exception ex){Toast.makeText(this,"Isi jumlah bukan nol, kategori, dan merchant",Toast.LENGTH_LONG).show();}}).show();}
    private void showInfo(){page="info";init("Tentang TapLedger","Alpha 0.1 • Offline by default");LinearLayout c=card(content);c.addView(text("Privasi & batasan",18,NAVY,true));c.addView(text("Aplikasi menyimpan identitas teknis kartu, tanggal pemindaian, dan transaksi yang Anda catat dalam database lokal. Catatan lokal tidak dikirim ke server TapLedger. Fitur situs operator membuka halaman online milik operator dan tunduk pada kebijakan situs tersebut.",14,GREY,false));c.addView(text("Belum tersedia: pembacaan saldo bank, parsing transaksi chip, klasifikasi operator otomatis, logo resmi, top-up, pembayaran atau sinkronisasi penerbit.",14,GREY,false));c.addView(text("UID NFC bukan bukti identitas unik yang aman. Struk adalah arsip pribadi, bukan bukti bayar dari bank atau operator tol.",14,GREY,false));}
    private String money(long n){boolean neg=n<0;return (neg?"−":"+")+"Rp"+String.format(new Locale("id","ID"),"%,d",Math.abs(n)).replace(',','.');}
    private void exportPdf(String[] r){PdfDocument doc=new PdfDocument();PdfDocument.Page page=doc.startPage(new PdfDocument.PageInfo.Builder(595,842,1).create());Canvas canvas=page.getCanvas();Paint p=new Paint(3);p.setColor(NAVY);p.setTextSize(28);p.setTypeface(Typeface.create(Typeface.DEFAULT,Typeface.BOLD));canvas.drawText("TapLedger",48,68,p);p.setTextSize(17);canvas.drawText("STRUK CATATAN PRIBADI",48,115,p);p.setColor(GREY);p.setTextSize(12);canvas.drawText("BUKAN BUKTI PEMBAYARAN RESMI",48,139,p);String[] lines={"Nomor catatan: TL-"+r[0],"Tanggal: "+fmt.format(new Date(Long.parseLong(r[2]))),"Kartu: ••••"+r[1].substring(Math.max(0,r[1].length()-4)),"Kategori: "+r[4],"Merchant: "+r[5],"Lokasi: "+r[6],"Operator: "+(r[9].isEmpty()?"Tidak diverifikasi":r[9]),"Jumlah: "+money(Long.parseLong(r[3])),"Sumber: dicatat manual","Catatan: "+r[7]};p.setColor(NAVY);p.setTextSize(14);int y=198;for(String line:lines){if(line.length()>69)line=line.substring(0,66)+"...";canvas.drawText(line,48,y,p);y+=35;}p.setColor(GREY);p.setTextSize(11);canvas.drawText("Arsip lokal — tidak dapat digunakan sebagai verifikasi pembayaran.",48,720,p);doc.finishPage(page);try{File dir=new File(getExternalFilesDir(null),"receipts");if(!dir.exists())dir.mkdirs();File file=new File(dir,"tapledger_receipt_"+r[0]+".pdf");try(FileOutputStream o=new FileOutputStream(file)){doc.writeTo(o);}new AlertDialog.Builder(this).setTitle("Struk PDF dibuat").setMessage("Disimpan di penyimpanan aplikasi:\n"+file.getAbsolutePath()+"\n\nStruk bukan bukti bayar resmi.").setPositiveButton("OK",null).show();}catch(Exception e){Toast.makeText(this,"Gagal membuat PDF: "+e.getMessage(),Toast.LENGTH_LONG).show();}finally{doc.close();}}
}
